function extraRecipeSteps(r) {
  const n = r.name.toLowerCase();
  if (n.includes('rice flour')) {
    if (n.includes('pudding') || n.includes('halwa')) return ['Whisk the rice flour with a little cool liquid until smooth.','Warm the remaining milk or coconut milk with the listed sweetener and flavourings.','Whisk in the rice-flour mixture over low heat, stirring continuously until thick and cooked through.','Finish with the listed nuts or toppings and serve warm or cooled.'];
    if (n.includes('idiyappam') || n.includes('steamed cakes') || n.includes('dumpling')) return ['Mix rice flour with hot water and salt to form a workable dough; add the listed filling ingredients as appropriate.','Shape into the form needed for this dish, keeping pieces evenly sized.','Steam until the dough is fully cooked and tender.','Serve warm with the listed coconut or accompaniment.'];
    if (n.includes('cookie') || n.includes('cracker')) return ['Mix rice flour with the listed oil or butter, seasonings and enough water to form a dough.','Shape or roll thinly on a clean surface.','Bake in a preheated oven until cooked and lightly golden, checking often.','Cool before serving so the texture can set.'];
    if (n.includes('pancake') || n.includes('chilla') || n.includes('dosa') || n.includes('crepe')) return ['Whisk rice flour with the listed liquid and seasonings until a smooth pourable batter forms.','Fold in the listed vegetables or flavourings and rest briefly.','Pour a thin layer into a lightly greased hot pan.','Cook both sides until set and lightly golden; serve hot.'];
    return ['Combine the rice flour with the listed ingredients and enough liquid to make a smooth mixture.','Cook gently in a greased pan or steamer, depending on the dish, until fully set.','Check the centre is cooked before removing from the heat.','Finish with the listed toppings and serve.'];
  }
  if (n.includes('pudding') || n.includes('porridge') || n.includes('payasam') || n.includes('pongal') || n.includes('halwa') || n.includes('sweet rice')) {
    return ['Rinse the rice if using whole rice, then add it to a saucepan with the listed milk, coconut milk or water.','Simmer gently, stirring regularly, until the rice is tender and the mixture thickens.','Add the listed sweetener and spices; cook a few more minutes until dissolved and fragrant.','Finish with the listed nuts or fruit and serve warm or chilled.'];
  }
  if (n.includes('fried rice')) {
    return ['Use cooked, cooled rice for the best texture; prepare and chop the listed vegetables and aromatics.','Heat a wide pan, add a little oil, and sauté garlic, onion or ginger from the ingredient list.','Add vegetables and any listed protein; cook thoroughly, especially chicken, egg or seafood.','Add rice and the listed sauces or seasonings. Toss over high heat until piping hot and serve.'];
  }
  if (n.includes('risotto')) {
    return ['Warm the stock in a separate saucepan and finely chop the listed vegetables.','Sauté onion and mushrooms or vegetables in butter or oil until softened.','Stir in the rice, then add warm stock a ladle at a time, stirring and allowing each addition to absorb.','Continue until the rice is tender and creamy; stir in the listed cheese, greens or lemon and serve promptly.'];
  }
  if (n.includes('soup')) {
    return ['Prepare and chop the listed vegetables, aromatics and protein.','Sauté onion, garlic or ginger from the ingredient list in a pot with a little oil.','Add the listed stock or water, rice and remaining ingredients; simmer until the rice and vegetables are tender and any meat or seafood is fully cooked.','Season to taste and serve hot.'];
  }
  if (n.includes('cutlet') || n.includes('pakora') || n.includes('patties') || n.includes('fritters') || n.includes('balls')) {
    return ['Cook or prepare the rice and listed vegetables, then mash or chop as needed.','Mix with the listed binding ingredients and seasonings until the mixture holds together.','Shape into small, even pieces and coat lightly if the recipe calls for it.','Pan-fry, bake or air-fry until golden and hot throughout; drain and serve.'];
  }
  if (n.includes('pancake') || n.includes('frittata') || n.includes('omelette')) {
    return ['Prepare the rice and finely chop the listed vegetables or herbs.','Mix rice with the listed eggs, dairy or flour and seasonings.','Cook in a lightly greased pan over medium-low heat until the base sets.','Flip carefully or cover to cook through; serve once the centre is fully set.'];
  }
  if (n.includes('biryani') || n.includes('pulao') || n.includes('pilaf') || n.includes('puliyogare') || n.includes('vangi bath') || n.includes('bisi bele bath')) {
    return ['Rinse the rice and prepare the listed vegetables, herbs and seasonings.','Heat oil or ghee in a heavy pot; sauté the aromatics and spices, then cook the vegetables or protein until ready for the rice.','Add rice and the appropriate amount of water or stock. For layered biryani, layer the partially cooked rice over the masala.','Cover and cook on low until the rice is tender and any meat or seafood is fully cooked; rest briefly before serving.'];
  }
  if (n.includes('curry') || n.includes('bowl') || n.includes('chawal') || n.includes('dal') || n.includes('masala') || n.includes('stew')) {
    return ['Cook the rice separately according to its package directions, then keep it warm.','Chop the listed vegetables and aromatics. Sauté onion, garlic or ginger in a little oil where included.','Add the listed vegetables, protein, spices and sauce ingredients with a splash of water; simmer until tender and fully cooked.','Taste and adjust seasoning, then serve the curry or topping over the rice.'];
  }
  return ['Cook the rice according to package directions and set aside.','Prepare the listed vegetables, herbs and other ingredients. Sauté the aromatics and seasonings in a pan with a little oil or ghee.','Add the main ingredients and cook until tender; ensure any meat, egg or seafood is fully cooked.','Fold in the rice or serve the prepared topping over it. Taste, adjust seasoning and serve hot.'];
}
const EXTRA_RECIPES = EXTRA_RECIPE_DATA.map(d => R(d.name, '🍚', d.ingredients, d.time, d.cuisine, d.meal, d.desc, extraRecipeSteps(d), d.diet));
RECIPES.push(...EXTRA_RECIPES);

// A few specialist pantry items used by the recipe collection.
INGREDIENTS.push(...[['Tamarind','🟤','Herbs & spices'],['Drumstick','🌿','Vegetables'],['Amchur','🫙','Herbs & spices'],['Ragi flour','🌾','Grains & pulses'],['Cocoa powder','🍫','Sauces & pantry'],['Lettuce','🥬','Vegetables'],['Flatbread / roti','🫓','Grains & pulses'],['Dried oregano','🌿','Herbs & spices'],['Ice','🧊','Sauces & pantry']].map(([name,emoji,category])=>({name,emoji,category})));
for (const recipe of EXTRA_RECIPES) for (const name of recipe.ingredients) { if (!INGREDIENTS.some(item => item.name === name)) INGREDIENTS.push({name, emoji:'🥣', category:'Other pantry'}); }

const $ = id => document.getElementById(id);
const STORE_KEY='whatsCookingKitchenV1';
let selected = new Set();
let activeCategory='All';
let showAllIngredients=false;
let activeResultFilter='all';
const PAGE_SIZE=12;
let currentRecipePage=1;
let matchedRecipes=[];
let toastTimer;
let pantry = loadStore().pantry || [];
let favorites = new Set(loadStore().favorites || []);
let recent = loadStore().recent || [];
let timerInterval=null, timerSeconds=0;
const CATEGORIES=['All',...new Set(INGREDIENTS.map(i=>i.category))];
function loadStore(){try{return JSON.parse(localStorage.getItem(STORE_KEY)||'{}')}catch{return {}}}
function saveStore(){const old=loadStore();localStorage.setItem(STORE_KEY,JSON.stringify({...old,pantry,favorites:[...favorites],recent}));renderPantry();}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function normalize(s){return String(s).toLowerCase().replace(/\([^)]*\)/g,'').replace(/[^a-z0-9]+/g,' ').trim()}
function findIngredient(text){const n=normalize(text);return INGREDIENTS.find(i=>normalize(i.name)===n)||INGREDIENTS.find(i=>n===normalize(i.name.split(' / ')[0]))||INGREDIENTS.find(i=>n.includes(normalize(i.name))||normalize(i.name).includes(n)&&n.length>2)}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function renderCategories(){ $('categories').innerHTML=CATEGORIES.map(c=>`<button class="category-chip ${activeCategory===c?'active':''}" data-category="${escapeHtml(c)}">${escapeHtml(c)}</button>`).join('') }
function renderIngredients(){const q=normalize($('ingredientSearch').value);let items=INGREDIENTS.filter(i=>(activeCategory==='All'||i.category===activeCategory)&&(!q||normalize(i.name).includes(q)));const limit=showAllIngredients||q?items.length:36;items=items.slice(0,limit);$('ingredientGrid').innerHTML=items.map(i=>`<button class="ingredient-card ${selected.has(i.name)?'selected':''}" data-ingredient="${escapeHtml(i.name)}" aria-pressed="${selected.has(i.name)}"><span class="food-emoji">${i.emoji}</span><span>${escapeHtml(i.name)}</span></button>`).join('')||'<p class="empty-selection">No ingredients found. Try another search or type your ingredient.</p>';$('showMore').classList.toggle('hidden',showAllIngredients||!!q||INGREDIENTS.filter(i=>activeCategory==='All'||i.category===activeCategory).length<=36);}
function renderSelected(){const names=[...selected];$('selectedCount').textContent=`${names.length} selected`;$('navCount').textContent=names.length;$('discoverCount').textContent=`${names.length} ingredient${names.length===1?'':'s'}`;$('selectedIngredients').innerHTML=names.length?names.map(n=>{const i=INGREDIENTS.find(x=>x.name===n);return `<span class="selected-chip">${i?.emoji||'🥣'} ${escapeHtml(n)} <button aria-label="Remove ${escapeHtml(n)}" data-remove="${escapeHtml(n)}">×</button></span>`}).join(''):'<p class="empty-selection">Your ingredient list will appear here. Pick a few things above to get started.</p>';renderIngredients()}
function addIngredient(name){const item=findIngredient(name);if(item){selected.add(item.name);return item.name}return null}
function parseTyped(){const text=$('typedIngredients').value.trim();if(!text){toast('Type a few ingredients first.');return}let added=[],unknown=[];text.split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean).forEach(raw=>{const match=findIngredient(raw.replace(/^\d+(\.\d+)?\s*(g|kg|ml|l|cups?|tbsp|tsp|pieces?|pcs)?\s*/i,''));if(match){selected.add(match.name);added.push(match.name)}else unknown.push(raw)});renderSelected();if(added.length){toast(`Added ${new Set(added).size} ingredient${new Set(added).size===1?'':'s'}.`);$('typedIngredients').value=unknown.join(', ')}if(unknown.length)toast(`Added known ingredients. Not in library: ${unknown.slice(0,3).join(', ')}${unknown.length>3?'…':''}`);if(!added.length)toast('No exact library matches. Try the ingredient picker or a simpler ingredient name.')}
function dietaryOK(r,diet){if(diet==='any')return true;if(diet==='vegetarian')return r.diet!=='nonveg';if(diet==='vegan')return r.diet==='vegan'||r.diet==='jain';if(diet==='egg')return r.diet==='egg';if(diet==='gluten-free')return !r.ingredients.some(n=>['Wheat flour','Whole wheat bread','Pasta','Noodles','Maida / all-purpose flour','Semolina / rava','Bread','Rava'].includes(n));if(diet==='jain')return r.diet==='jain'||!r.ingredients.some(n=>['Onion','Garlic','Potato','Carrot','Radish','Ginger','Beetroot','Sweet potato'].includes(n));return true}
function ingredientEquivalent(a,b){
 const x=normalize(a), y=normalize(b);
 if(x===y) return true;
 const riceFamily=new Set(['rice','basmati rice']);
 return riceFamily.has(x)&&riceFamily.has(y);
}
function selectedHasIngredient(name){return [...selected].some(chosenName=>ingredientEquivalent(name,chosenName));}
function getRecipeScore(r){const have=r.ingredients.filter(n=>selectedHasIngredient(n));const missing=r.ingredients.filter(n=>!selectedHasIngredient(n)&&!['Salt','Water','Cooking oil','Sugar','Black pepper'].includes(n));const required=r.ingredients.filter(n=>!['Salt','Water','Cooking oil','Sugar','Black pepper'].includes(n));const matched=required.filter(n=>selectedHasIngredient(n));const score=required.length?Math.round(matched.length/required.length*100):0;const direct=have.length;return {...r,have,missing,required,matched,score,direct,missingCount:missing.length,rank:score*1.3+direct*3-missing.length*.35}}
function getMatches(){const meal=$('mealType').value,time=$('timeLimit').value,diet=$('diet').value,cuisine=$('cuisine').value;let arr=RECIPES.map(getRecipeScore).filter(r=>dietaryOK(r,diet));if(meal!=='any')arr=arr.filter(r=>r.meal.toLowerCase()===meal.toLowerCase());if(time!=='any')arr=arr.filter(r=>r.time<=Number(time));if(cuisine!=='any')arr=arr.filter(r=>r.cuisine.toLowerCase()===cuisine.toLowerCase()||cuisine==='Indian'&&r.cuisine.toLowerCase().includes('indian'));if(selected.size){arr=arr.filter(r=>r.direct>0);if($('useSoon').checked){const soon=new Set(pantry.filter(p=>p.soon).map(p=>p.name));arr=arr.map(r=>({...r,soonCount:r.ingredients.filter(n=>soon.has(n)).length,rank:r.rank+r.ingredients.filter(n=>soon.has(n)).length*12}))}}else{arr=[]}return arr}
function imageFor(r){if(r.image)return r.image;const queries={'Indian':'photo-1585937421612-70a008356fbe','South Indian':'photo-1630383249896-424e482df921','North Indian':'photo-1565557623262-b51c2513a641','Italian':'photo-1473093295043-cdd812d0e601','Asian':'photo-1569718212165-3a8278d5f624','Global':'photo-1547592180-85f173990554','West Indian':'photo-1603894584373-5ac82b2ae398','Fusion':'photo-1547592180-85f173990554'};const id=queries[r.cuisine]||queries.Global;return `https://images.unsplash.com/${id}?auto=format&fit=crop&w=700&q=75`}
function resultCard(r){const img=imageFor(r);const missing=r.missingCount;return `<article class="recipe-card"><div class="recipe-image"><img loading="lazy" src="${img}" alt="${escapeHtml(r.name)}" onerror="this.style.display='none';this.nextElementSibling.classList.remove('hidden')"><span class="image-emoji hidden">${r.emoji}</span><span class="match-badge">${r.score>=90?'READY TO COOK':r.score>=55?'GREAT MATCH':r.score>0?'POSSIBLE MATCH':'IDEA TO TRY'}</span><button class="favorite-btn ${favorites.has(r.name)?'active':''}" data-favorite="${escapeHtml(r.name)}" aria-label="Save ${escapeHtml(r.name)}">${favorites.has(r.name)?'♥':'♡'}</button></div><div class="recipe-body"><div class="recipe-meta"><span>◷ ${r.time} min</span><span>${escapeHtml(r.cuisine)}</span><span>${escapeHtml(r.meal)}</span></div><h3>${escapeHtml(r.name)}</h3><p>${escapeHtml(r.desc)}</p><div class="match-line"><span style="width:${r.score}%"></span></div><div class="match-text"><span>${r.matched.length} of ${r.required.length} key ingredients</span><b>${r.score}% match</b></div><div class="recipe-tags"><span>${r.diet==='nonveg'?'Non-vegetarian':r.diet==='vegan'?'Vegan':r.diet==='egg'?'Egg-based':'Vegetarian'}</span><span>${r.time<=15?'Quick & easy':r.time<=30?'Everyday':'Worth the time'}</span></div><div class="recipe-card-footer"><span class="missing-text">${missing===0?'✓ Essentials covered':`${missing} item${missing===1?'':'s'} to check`}</span><button class="view-recipe" data-recipe="${escapeHtml(r.name)}">View recipe ↗</button></div></div></article>`}
function renderResults(scroll=false){
 if(!selected.size){$('resultsTitle').innerHTML='A little inspiration, <em>coming up.</em>';$('resultsSubtitle').textContent='Add ingredients to discover dishes made for you.';$('recipeGrid').innerHTML='<div class="results-empty"><div class="empty-illustration">🥘</div><h3>Your next meal is waiting.</h3><p>Select ingredients above and we’ll match them to dishes in our recipe collection.</p><button class="secondary-btn" id="emptyStart">Choose ingredients →</button></div>';$('pagination').classList.add('hidden');return}
 matchedRecipes=getMatches();const sort=$('sortBy').value;if(sort==='time')matchedRecipes.sort((a,b)=>a.time-b.time||b.rank-a.rank);else if(sort==='name')matchedRecipes.sort((a,b)=>a.name.localeCompare(b.name));else matchedRecipes.sort((a,b)=>b.rank-a.rank);if(activeResultFilter==='ready')matchedRecipes=matchedRecipes.filter(r=>r.missingCount===0);if(activeResultFilter==='missing')matchedRecipes=matchedRecipes.filter(r=>r.missingCount>0&&r.missingCount<=3);if(activeResultFilter==='quick')matchedRecipes=matchedRecipes.filter(r=>r.time<=20);
 const pageCount=Math.max(1,Math.ceil(matchedRecipes.length/PAGE_SIZE));currentRecipePage=Math.min(currentRecipePage,pageCount);$('resultsTitle').innerHTML=`${matchedRecipes.length} dishes for <em>your kitchen.</em>`;$('resultsSubtitle').textContent=`${selected.size} ingredients selected · ${RECIPES.length} recipes in this collection · Page ${currentRecipePage} of ${pageCount}`;
 const start=(currentRecipePage-1)*PAGE_SIZE;const toShow=matchedRecipes.slice(start,start+PAGE_SIZE);$('recipeGrid').innerHTML=toShow.length?toShow.map(resultCard).join(''):'<div class="results-empty"><div class="empty-illustration">🌱</div><h3>No matches for these filters.</h3><p>Try changing the filters or adding another ingredient.</p><button class="secondary-btn" id="resetFilters">Reset filters →</button></div>';
 $('pagination').classList.toggle('hidden',matchedRecipes.length<=PAGE_SIZE);$('prevPage').disabled=currentRecipePage<=1;$('nextPage').disabled=currentRecipePage>=pageCount;$('pageStatus').textContent=`Page ${currentRecipePage} of ${pageCount}`;
 if(scroll){document.body.classList.add('results-mode');window.scrollTo({top:0,behavior:'instant'});}
}
function openRecipe(name){const r=getRecipeScore(RECIPES.find(x=>x.name===name));if(!r)return;recent=[name,...recent.filter(n=>n!==name)].slice(0,8);saveStore();const ingredients=r.ingredients.map(n=>`<li><label><input type="checkbox"> ${escapeHtml(n)}${selected.has(n)?' <span style="color:#638158">(you have this)</span>':''}</label></li>`).join('');const steps=r.steps.map((s,i)=>`<li>${escapeHtml(s)}</li>`).join('');const missing=r.missing.filter(n=>!['Salt','Water','Cooking oil','Sugar','Black pepper'].includes(n));$('modalContent').innerHTML=`<div class="modal-hero"><img src="${imageFor(r)}" alt="${escapeHtml(r.name)}" onerror="this.style.display='none';this.parentElement.insertAdjacentHTML('beforeend','<span>${r.emoji}</span>')"></div><div class="modal-kicker">${escapeHtml(r.cuisine.toUpperCase())} · ${escapeHtml(r.meal.toUpperCase())}</div><h2 id="modalTitle">${escapeHtml(r.name)}</h2><p class="modal-description">${escapeHtml(r.desc)} ${r.score?`You have ${r.have.length} of this recipe’s ingredients.`:''}</p><div class="modal-stats"><span>◷ ${r.time} minutes</span><span>♧ ${$('servings').value} servings</span><span>${r.diet==='nonveg'?'Non-vegetarian':r.diet==='vegan'?'Vegan':r.diet==='egg'?'Egg-based':'Vegetarian'}</span></div>${missing.length?`<div class="missing-box"><b>Before you start:</b> Check whether you have ${missing.map(escapeHtml).join(', ')}. The recipe is still available to view.</div>`:''}<div class="modal-columns"><div><h3>Ingredients</h3><ul>${ingredients}</ul><button class="secondary-btn" id="modalShopping">Add missing to shopping list ↗</button></div><div><h3>Let's make it</h3><ol>${steps}</ol><div class="cook-controls"><button id="startTimer" data-minutes="${Math.max(1,Math.min(30,Math.round(r.time/Math.max(2,r.steps.length))))}">Start a ${Math.max(1,Math.min(30,Math.round(r.time/Math.max(2,r.steps.length))))}-min timer</button><button id="markCooked">✓ I've made this</button></div><div class="timer-display" id="timerDisplay"></div></div></div>`;$('modal').classList.remove('hidden');document.body.style.overflow='hidden';$('modalClose').focus()}
function closeModal(){$('modal').classList.add('hidden');document.body.style.overflow='';if(timerInterval){clearInterval(timerInterval);timerInterval=null}}
function renderPantry(){const soon=pantry.filter(p=>p.soon).length;$('pantryTotal').textContent=pantry.length;$('pantrySoon').textContent=soon;$('pantryItems').innerHTML=pantry.length?pantry.map(p=>`<div class="pantry-item"><span>${INGREDIENTS.find(i=>i.name===p.name)?.emoji||'🥣'}</span><span>${escapeHtml(p.name)}</span>${p.soon?'<span class="soon">USE SOON</span>':''}<button data-pantry-remove="${escapeHtml(p.name)}" aria-label="Remove">×</button></div>`).join():'<p>Your saved ingredients will show up here.</p>'}
function saveSelectedPantry(){if(!selected.size){toast('Select ingredients first, then save them here.');return}const existing=new Set(pantry.map(p=>p.name));let added=0;for(const name of selected){if(!existing.has(name)){pantry.push({name,soon:false});added++}}saveStore();toast(added?`Saved ${added} ingredient${added===1?'':'s'} to your kitchen.`:'Those ingredients are already in your kitchen.');$('pantry').scrollIntoView({behavior:'smooth'})}
function setTab(tab){document.querySelectorAll('.input-tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));['select','type','photo'].forEach(t=>$(`${t}Panel`).classList.toggle('hidden',t!==tab))}
// UI events
document.querySelectorAll('.input-tab').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));
$('categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;activeCategory=b.dataset.category;renderCategories();renderIngredients()});
$('ingredientGrid').addEventListener('click',e=>{const b=e.target.closest('[data-ingredient]');if(!b)return;const n=b.dataset.ingredient;selected.has(n)?selected.delete(n):selected.add(n);renderSelected()});
$('ingredientSearch').addEventListener('input',()=>renderIngredients());$('clearSearch').addEventListener('click',()=>{$('ingredientSearch').value='';activeCategory='All';renderCategories();renderIngredients()});$('showMore').addEventListener('click',()=>{showAllIngredients=true;renderIngredients()});
$('selectedIngredients').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b){selected.delete(b.dataset.remove);renderSelected()}});$('clearAll').addEventListener('click',()=>{selected.clear();renderSelected();toast('Ingredient list cleared.')});$('addTyped').addEventListener('click',parseTyped);
$('photoInput').addEventListener('change',e=>{const files=[...e.target.files];if(!files.length)return;const valid=files.filter(f=>f.type.startsWith('image/'));if(!valid.length){toast('Please upload a photo file of ingredients.');e.target.value='';return}const f=valid[0];const url=URL.createObjectURL(f);$('photoPreview').innerHTML=`<img src="${url}" alt="Uploaded photo preview"><div><b>${escapeHtml(f.name)}</b><span>${(f.size/1024/1024).toFixed(2)} MB · ${valid.length>1?valid.length+' images selected':'Photo ready to review'}</span><button id="removePhoto">Remove photo</button><span>Use the ingredient picker to confirm what is visible.</span></div>`;$('photoPreview').classList.remove('hidden');$('removePhoto').addEventListener('click',()=>{$('photoInput').value='';$('photoPreview').classList.add('hidden');$('photoPreview').innerHTML=''});toast('Photo loaded. Confirm visible ingredients using the picker.');});
$('uploadZone').addEventListener('dragover',e=>{e.preventDefault();$('uploadZone').style.background='#e5eddf'});$('uploadZone').addEventListener('dragleave',()=>$('uploadZone').style.background='');$('uploadZone').addEventListener('drop',e=>{e.preventDefault();$('uploadZone').style.background='';const files=[...e.dataTransfer.files].filter(f=>f.type.startsWith('image/'));if(!files.length){toast('Please drop an image file of your ingredients.');return}const dt=new DataTransfer();files.forEach(f=>dt.items.add(f));$('photoInput').files=dt.files;$('photoInput').dispatchEvent(new Event('change'))});
$('discoverBtn').addEventListener('click',()=>{currentRecipePage=1;activeResultFilter='all';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));renderResults(true);});$('sortBy').addEventListener('change',()=>{currentRecipePage=1;renderResults()});$('resultFilters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;activeResultFilter=b.dataset.filter;currentRecipePage=1;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderResults()});$('recipeGrid').addEventListener('click',e=>{const fav=e.target.closest('[data-favorite]');if(fav){const n=fav.dataset.favorite;favorites.has(n)?favorites.delete(n):favorites.add(n);saveStore();renderResults();toast(favorites.has(n)?'Saved to favourites.':'Removed from favourites.');return}const recipe=e.target.closest('[data-recipe]');if(recipe){openRecipe(recipe.dataset.recipe);return}if(e.target.id==='emptyStart'){document.body.classList.remove('results-mode');$('finder').scrollIntoView({behavior:'smooth'});}if(e.target.id==='resetFilters'){$('mealType').value='any';$('timeLimit').value='any';$('diet').value='any';$('cuisine').value='any';activeResultFilter='all';currentRecipePage=1;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));renderResults()}});$('prevPage').addEventListener('click',()=>{if(currentRecipePage>1){currentRecipePage--;renderResults();window.scrollTo({top:0,behavior:'instant'});}});$('nextPage').addEventListener('click',()=>{if(currentRecipePage<Math.ceil(matchedRecipes.length/PAGE_SIZE)){currentRecipePage++;renderResults();window.scrollTo({top:0,behavior:'instant'});}});$('backToKitchen').addEventListener('click',()=>{document.body.classList.remove('results-mode');$('finder').scrollIntoView({behavior:'smooth',block:'start'});});
$('modalClose').addEventListener('click',closeModal);$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('modalContent').addEventListener('click',e=>{if(e.target.id==='modalShopping'){const r=RECIPES.find(x=>x.name===$('modalTitle').textContent);if(!r)return;const missing=r.ingredients.filter(n=>!selected.has(n)&&!['Salt','Water','Cooking oil','Sugar','Black pepper'].includes(n));const old=loadStore().shopping||[];const list=[...new Set([...old,...missing])];localStorage.setItem(STORE_KEY,JSON.stringify({...loadStore(),shopping:list,pantry,favorites:[...favorites],recent}));toast(missing.length?`Added ${missing.length} missing ingredients to your saved shopping list.`:'You appear to have all listed ingredients.');}if(e.target.id==='markCooked'){const n=$('modalTitle').textContent;recent=[n,...recent.filter(x=>x!==n)].slice(0,8);saveStore();toast('Nice work! Added to your cooking history.');e.target.textContent='✓ Added to history';}if(e.target.id==='startTimer'){if(timerInterval)clearInterval(timerInterval);timerSeconds=Number(e.target.dataset.minutes)*60;const out=$('timerDisplay');const tick=()=>{out.textContent=`${Math.floor(timerSeconds/60).toString().padStart(2,'0')}:${(timerSeconds%60).toString().padStart(2,'0')}`;if(timerSeconds<=0){clearInterval(timerInterval);timerInterval=null;out.textContent='⏰ Timer finished!';toast('Your cooking timer is finished.');return}timerSeconds--};tick();timerInterval=setInterval(tick,1000);e.target.textContent='Restart timer'}});
$('pantryItems').addEventListener('click',e=>{const b=e.target.closest('[data-pantry-remove]');if(!b)return;pantry=pantry.filter(p=>p.name!==b.dataset.pantryRemove);saveStore()});$('savePantry').addEventListener('click',saveSelectedPantry);$('pantryBtn').addEventListener('click',()=>{$('pantry').scrollIntoView({behavior:'smooth'});toast('Your pantry is saved in this browser.')});
function scrollToFinder(){ document.body.classList.remove('results-mode');$('finder').scrollIntoView({behavior:'smooth'});setTab('select') }['startBtn','heroStart','bottomStart','emptyStart'].forEach(id=>{const el=$(id);if(el)el.addEventListener('click',scrollToFinder)});$('mobileMenu').addEventListener('click',()=>document.querySelector('.topbar').classList.toggle('menu-open'));document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('.topbar').classList.remove('menu-open')));
renderCategories();renderIngredients();renderSelected();renderPantry();
